import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Releases","description":"","frontmatter":{},"headers":[],"relativePath":"operations/releases.md","filePath":"operations/releases.md","lastUpdated":null}'),r={name:"operations/releases.md"};function l(i,e,c,n,d,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h1><p>Releases are tag-driven. A tag matching <code>v*</code> runs the release job in <code>.github/workflows/ci.yml</code> after the verification job succeeds.</p><h2 id="what-a-release-publishes" tabindex="-1">What a release publishes <a class="header-anchor" href="#what-a-release-publishes" aria-label="Permalink to &quot;What a release publishes&quot;">​</a></h2><ul><li>A multi-architecture operator image for <code>linux/amd64</code> and <code>linux/arm64</code> to GHCR.</li><li>An SPDX SBOM attached as a workflow artifact.</li><li>A Cosign signature for the image.</li><li>A Helm chart pushed to the GHCR OCI registry.</li></ul><p>The image and chart use the tag version without the leading <code>v</code> as their application version. Keep the tag semver-compatible because Helm receives it as <code>--version</code>.</p><h2 id="release-checklist" tabindex="-1">Release checklist <a class="header-anchor" href="#release-checklist" aria-label="Permalink to &quot;Release checklist&quot;">​</a></h2><ol><li>Confirm the .NET and KubeOps versions in <code>global.json</code> and <code>src/AegisScan.Operator/AegisScan.Operator.csproj</code>.</li><li>Run <code>dotnet test AegisScan.sln</code> and the frontend tests locally.</li><li>Run the Compose k3s test plan, including the browser suite.</li><li>Create and push a tag such as <code>v0.2.0</code>.</li><li>Verify the GHCR image signature, SBOM artifact, and Helm OCI package.</li><li>Deploy the chart from the OCI registry and check the operator health/readiness probes.</li></ol><h2 id="image-provenance" tabindex="-1">Image provenance <a class="header-anchor" href="#image-provenance" aria-label="Permalink to &quot;Image provenance&quot;">​</a></h2><p>The workflow requires <code>packages: write</code> and <code>id-token: write</code>. Keep those permissions scoped to the release job. Do not place registry credentials in repository files or Helm values.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back by selecting the previous immutable image tag and chart version. Do not reuse a mutable <code>latest</code> tag for production deployments. Restore CRDs independently and follow <a href="/operations/crd-upgrades">CRD upgrades</a> when a release changes the schema.</p>',11)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
